@import "@fontsource-variable/figtree";
@import "@fontsource/space-mono/400.css";
@import "@fontsource/space-mono/700.css";
@import "@fontsource/la-belle-aurore/400.css";

/* Light (faithful): white page, aubergine #281350 ink and dark bands, violet #5f2ee5
   actions, butter-yellow #ffd967 main CTA and arcs, candy pink #f891ff bar and callouts,
   cyan #8eecff media cards (their 20% tint is the pale cyan band). */
:root {
  --background: #ffffff;
  --foreground: #281350;
  --card: #ffffff;
  --card-foreground: #281350;
  --popover: #ffffff;
  --popover-foreground: #281350;
  --primary: #5f2ee5;
  --primary-foreground: #ffffff;
  --secondary: #281350;
  --secondary-foreground: #ffffff;
  --muted: #f6f3ff;
  --muted-foreground: #5e5a66;
  --accent: #8eecff;
  --accent-foreground: #281350;
  --destructive: #ce1836;
  --destructive-foreground: #ffffff;
  --border: #e9e7ed;
  --input: #e0e0e0;
  --ring: #825beb;
  --highlight: #ffd967;
  --highlight-foreground: #281350;
  --glow: #f891ff;
  --chart-1: #5f2ee5;
  --chart-2: #8eecff;
  --chart-3: #ffd967;
  --chart-4: #f3ffd3;
  --chart-5: #967000;
  --sidebar: #f6f3ff;
  --sidebar-foreground: #281350;
  --sidebar-primary: #5f2ee5;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f2edff;
  --sidebar-accent-foreground: #281350;
  --sidebar-border: #e9e7ed;
  --sidebar-ring: #825beb;

  --typeface-body: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Space Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* closing lines only: blocks read it as var(--typeface-script, cursive) */
  --typeface-script: "La Belle Aurore", cursive;
  --radius: 1rem;
  --page-width: 80rem;
  --page-gutter: 1.5rem;
  --section-y: 4.5rem;
}

/* Dark sibling: a deep aubergine page, deeper bands, the same yellow and pink, a lighter
   violet so it reads on the dark. */
.dark {
  --background: #170a30;
  --foreground: #f3efff;
  --card: #22123f;
  --card-foreground: #f3efff;
  --popover: #22123f;
  --popover-foreground: #f3efff;
  --primary: #7b55f0;
  --primary-foreground: #ffffff;
  --secondary: #0e0520;
  --secondary-foreground: #f3efff;
  --muted: #2a1a4e;
  --muted-foreground: #bdb5d4;
  --accent: #2f9fb8;
  --accent-foreground: #170a30;
  --destructive: #f0586f;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 12%);
  --input: rgb(255 255 255 / 18%);
  --ring: #a58bf5;
  --highlight: #ffd967;
  --highlight-foreground: #281350;
  --glow: #f891ff;
  --chart-1: #8f6cf3;
  --chart-2: #2f9fb8;
  --chart-3: #ffd967;
  --chart-4: #3d4a1c;
  --chart-5: #e3bf4f;
  --sidebar: #0e0520;
  --sidebar-foreground: #f3efff;
  --sidebar-primary: #7b55f0;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #2a1a4e;
  --sidebar-accent-foreground: #f3efff;
  --sidebar-border: rgb(255 255 255 / 12%);
  --sidebar-ring: #a58bf5;
}
